const stdout = $input.item.json.stdout || '';

// Split into CONFIG, PROCESSED, and CV sections
const configSplit = stdout.split('---PROCESSED---');
const configPart = (configSplit[0] || '').replace('---CONFIG---', '').trim();

const processedAndCV = configSplit[1] || '';
const cvSplit = processedAndCV.split('---CV---');
const processedPart = cvSplit[0] || '';
const cvContent = (cvSplit[1] || '').trim();

let config = {};
try {
  config = JSON.parse(configPart);
} catch(e) {
  console.log('Config parse error:', e.message);
}

const processedLinks = processedPart
  .split('\n')
  .map(line => line.trim())
  .filter(line => line && !line.startsWith('#') && line.startsWith('http'));

console.log('Loaded ' + processedLinks.length + ' previously processed job links');
console.log('CV loaded: ' + (cvContent.length > 0 ? cvContent.length + ' chars' : 'NOT FOUND'));

const now = new Date();
const timestamp = now.toISOString().replace(/[:.]/g, '-').slice(0, 19);

return [{
  json: {
    jobTitles: config.job_titles || ['Engineering Manager'],
    location: config.location || 'London, UK',
    timeRange: config.time_range || '48h',
    excludeInTitle: config.exclude_in_title || [],
    excludeInDescription: config.exclude_in_description || [],
    flagForReview: config.flag_for_review || [],
    mustHaveKeywords: config.must_have || [],
    minScore: config.min_score || 7,
    maxJobs: config.max_jobs_per_title || 0,
    maxJobsTotal: config.max_jobs_total || 999,
    debugMode: config.debug_mode || false,
    skipCoverLetters: config.skip_cover_letters || false,
    ollamaModel: config.ollama_model || 'qwen2.5:latest',
    ollamaUrl: config.ollama_url || 'http://host.docker.internal:11434',
    runTimestamp: timestamp,
    processedLinks: processedLinks,
    cvContent: cvContent
  }
}];

// Parse jobs and prepare for processing
const jobsText = $input.item.json.stdout || '[]';
let allJobs = [];

try {
  allJobs = JSON.parse(jobsText);
} catch(e) {
  console.log('JSON parse error:', e.message);
  allJobs = [];
}

const config = $('Parse Config').item.json;
const searchTitle = $('Loop Job Titles').item.json.jobTitles;

// Filter out already processed jobs
const processedLinks = new Set(config.processedLinks || []);
const newJobs = [];
const skippedJobs = [];

for (const job of allJobs) {
  const link = job.job_link || '';
  if (link && processedLinks.has(link)) {
    skippedJobs.push(job);
  } else {
    newJobs.push(job);
  }
}

console.log(searchTitle + ': ' + newJobs.length + ' new jobs, ' + skippedJobs.length + ' skipped');

if (newJobs.length === 0 && skippedJobs.length === 0) {
  return [{ json: { noJobs: true, searchTitle, config } }];
}

// Pass all data to the next node
return [{
  json: {
    noJobs: false,
    searchTitle: searchTitle,
    config: config,
    newJobs: newJobs,
    skippedJobs: skippedJobs
  }
}];

// Prepare merge command - get timestamp from Parse Config
const config = $('Parse Config').item.json;
const timestamp = config.runTimestamp;

// Pattern to match all analysis files from this run
const inputPattern = '/data/n8n_linkedin/output/analysis_*_' + timestamp + '.xlsx';
const outputFile = '/data/n8n_linkedin/output/ALL_JOBS_' + timestamp + '.xlsx';

console.log('Merging all analysis files into: ' + outputFile);

return [{
  json: {
    inputPattern: inputPattern,
    outputFile: outputFile,
    timestamp: timestamp
  }
}];

// Analyze ALL jobs for this search title and prepare batch output
const input = $input.item.json;
const config = input.config;
const searchTitle = input.searchTitle;
const newJobs = input.newJobs || [];
const skippedJobs = input.skippedJobs || [];

// Generate per-search Excel filename
const safeTitle = searchTitle.replace(/[^a-zA-Z0-9]/g, '_').replace(/_+/g, '_');
const timestamp = config.runTimestamp;
const outputExcel = '/data/n8n_linkedin/output/analysis_' + safeTitle + '_' + timestamp + '.xlsx';

console.log('=== Analyzing ' + newJobs.length + ' jobs for: ' + searchTitle + ' ===');
console.log('Output: ' + outputExcel);

const excludeInTitle = (config.excludeInTitle || []).map(k => k.toLowerCase());
const excludeInDescription = (config.excludeInDescription || []).map(k => k.toLowerCase());

const batchResults = [];
const newLinks = [];

// Add skipped jobs to batch
for (const job of skippedJobs) {
  batchResults.push({
    timestamp: new Date().toISOString(),
    search_title: searchTitle,
    job_title: job.title || 'Unknown',
    company: job.company || 'Unknown',
    job_link: job.job_link || '',
    decision: 'SKIPPED',
    reason: 'Already processed',
    score: ''
  });
}

// Process new jobs
let idx = 0;
for (const job of newJobs) {
  idx++;
  let decision = 'UNKNOWN';
  let reason = '';
  let score = 0;

  console.log('[' + idx + '/' + newJobs.length + '] ' + job.title);

  const titleLower = (job.title || '').toLowerCase();
  const descLower = (job.description || '').toLowerCase();

  // TIER 1: Title rejection
  let rejected = false;
  for (const kw of excludeInTitle) {
    if (titleLower.includes(kw)) {
      decision = 'REJECTED_TITLE';
      reason = 'Title contains: ' + kw;
      rejected = true;
      console.log('  -> REJECTED (title)');
      break;
    }
  }

  // TIER 2: Description rejection
  if (!rejected) {
    for (const kw of excludeInDescription) {
      if (descLower.includes(kw)) {
        decision = 'REJECTED_DESC';
        reason = 'Description contains: ' + kw;
        rejected = true;
        console.log('  -> REJECTED (desc)');
        break;
      }
    }
  }

  // TIER 3: AI Analysis
  if (!rejected) {
    console.log('  -> Calling AI...');

    // Get CV content from config
    const cvContent = config.cvContent || '';
    const cvSummary = cvContent.substring(0, 2500); // Use first 2500 chars of CV

    const systemPrompt = 'You are a job matching expert. Analyze if the job description matches the candidate CV. Return JSON only.\n\n' +
      'SCORING CRITERIA:\n' +
      '- 9-10: Perfect match - role aligns with experience, seniority, and domain\n' +
      '- 7-8: Good match - most requirements align, minor gaps acceptable\n' +
      '- 5-6: Partial match - some alignment but significant gaps\n' +
      '- 1-4: Poor match - wrong seniority, domain, or role type\n\n' +
      'REJECT if: Individual contributor coding role, hardware/electrical engineering, junior/entry level, non-software domain (construction, healthcare, finance, legal), requires skills not in CV.\n\n' +
      'MATCH if: Engineering/QA management role, team leadership, test/release management, CI/CD, agile, software quality.\n\n' +
      'Return JSON: {relevant: boolean, rejection_reason: string (if not relevant), score: number (1-10), match_reasons: array of strings (top 3 reasons)}';

    const cleanDesc = (job.description || '').substring(0, 2000).replace(/[\x00-\x1F\x7F]/g, ' ').replace(/\s+/g, ' ');
    const userPrompt = 'CANDIDATE CV:\n' + cvSummary + '\n\n---\n\nJOB TO ANALYZE:\nTitle: ' + job.title + '\nCompany: ' + job.company + '\nDescription: ' + cleanDesc + '\n\nAnalyze if this job matches the candidate. Return JSON only.';

    let analysis = { relevant: false, rejection_reason: 'Analysis failed', score: 0, match_reasons: [] };

    try {
      const response = await this.helpers.httpRequest({
        method: 'POST',
        url: (config.ollamaUrl || 'http://host.docker.internal:11434') + '/api/chat',
        body: {
          model: config.ollamaModel || 'qwen2.5:latest',
          messages: [
            { role: 'system', content: systemPrompt },
            { role: 'user', content: userPrompt }
          ],
          stream: false,
          options: { temperature: 0.3 }
        },
        json: true,
        timeout: 120000
      });

      let txt = response.message?.content || '';
      txt = txt.replace(/```json\n?/gi, '').replace(/```\n?/g, '').trim();
      const m = txt.match(/\{[\s\S]*\}/);
      if (m) analysis = JSON.parse(m[0]);
    } catch(e) {
      console.log('  -> AI Error: ' + e.message);
      analysis.rejection_reason = 'AI error';
    }

    score = parseInt(analysis.score) || 0;

    if (analysis.relevant === true && score >= (config.minScore || 7)) {
      decision = 'MATCHED';
      reason = (analysis.match_reasons || []).slice(0, 3).join('; ') || 'Met criteria';
      console.log('  -> MATCHED (score ' + score + ')');
    } else {
      decision = 'REJECTED_AI';
      reason = analysis.rejection_reason || 'Score ' + score;
      console.log('  -> REJECTED (score ' + score + ')');
    }
  }

  // Add to batch
  batchResults.push({
    timestamp: new Date().toISOString(),
    search_title: searchTitle,
    job_title: (job.title || '').replace(/"/g, '').replace(/'/g, ''),
    company: (job.company || '').replace(/"/g, '').replace(/'/g, ''),
    job_link: job.job_link || '',
    decision: decision,
    reason: (reason || '').replace(/"/g, '').replace(/'/g, '').substring(0, 200),
    score: String(score)
  });

  // Track new link for processed_jobs.txt
  if (job.job_link) {
    newLinks.push(job.job_link);
  }
}

console.log('=== Done: ' + batchResults.length + ' total results ===');

// Encode batch data as base64 for shell command
const batchB64 = Buffer.from(JSON.stringify(batchResults)).toString('base64');

// Return single item with batch data already encoded
return [{
  json: {
    outputExcel: outputExcel,
    batchB64: batchB64,
    batchCount: batchResults.length,
    newLinks: newLinks,
    searchTitle: searchTitle
  }
}];
